/// Binary search of an area's zone-id table: `zones` is the area's zone ids
/// minus their `Area/` prefix (`"Abidjan"`, `"Accra"`, …) concatenated in
/// ascending order and `starts` their `N + 1` byte boundaries, so a hit's
/// position *is* the area's zone index.
///
/// Same reason as `name_lookup` below: as a `match` on `&str` the eleven
/// areas' zone tables inlined into 16 KB of compare chains; as data they
/// are ~5 KB of arena plus offsets and ~1.5 KB of code, with nothing per
/// zone.
#[cfg(any(
    feature = "tz-names-africa",
    feature = "tz-names-america",
    feature = "tz-names-antarctica",
    feature = "tz-names-arctic",
    feature = "tz-names-asia",
    feature = "tz-names-atlantic",
    feature = "tz-names-australia",
    feature = "tz-names-etc",
    feature = "tz-names-europe",
    feature = "tz-names-indian",
    feature = "tz-names-pacific",
))]
fn zone_lookup(zones: &str, starts: &[u16], rest: &str) -> Option<u16> {
    let mut lo = 0usize;
    let mut hi = starts.len().checked_sub(1)?;
    while lo < hi {
        let mid = (lo + hi) / 2;
        let at = zones.get(*starts.get(mid)? as usize..*starts.get(mid + 1)? as usize)?;
        if at < rest {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    let at = zones.get(*starts.get(lo)? as usize..*starts.get(lo + 1)? as usize)?;
    if at == rest { Some(lo as u16) } else { None }
}

/// Resolve `key` in one (area, locale) name table.
///
/// `runs` bounds locale `loc`'s slice of the parallel `keys`/`ids` arrays;
/// `keys` ascends within a run, so the lookup is a single binary search.
/// `ids[i]` names a string by its index into `strings`, the `D + 1` byte
/// boundaries of the area's deduplicated `arena`. Boundaries always fall on
/// char boundaries — the arena is whole strings concatenated — so the slice
/// never splits a codepoint; `get` is used anyway so a corrupt table would
/// return `None` rather than panic.
///
/// These tables are deliberately *data*, not the `match` shape the rest of
/// the generated code uses. They hold 67 060 name references over 1 111
/// (area, locale) pairs, and LLVM compiles a `match` that wide into a jump
/// table plus one code block per arm to materialize the `&'static str` fat
/// pointer. Measured on a release probe (`datetime,alloc` vs the same plus
/// `tz-names`), that shape added 1 098 KB of `.text` and 3 182 KB of
/// `.rodata` — 4 254 KB — to hold 1 523 KB of distinct strings, and left
/// 2 954 indirect jumps in the binary. As arrays the same tables add
/// 2 024 KB, of which 12 KB is code, with 247 indirect jumps and no
/// relocations. The `match` shape is the right one for the Unicode property
/// tables (dense integer -> small enum, which LLVM turns into a byte
/// lookup); it does not transfer to a wide string table. Please do not
/// "simplify" it back.
#[cfg(any(
    feature = "tz-names-africa",
    feature = "tz-names-america",
    feature = "tz-names-antarctica",
    feature = "tz-names-arctic",
    feature = "tz-names-asia",
    feature = "tz-names-atlantic",
    feature = "tz-names-australia",
    feature = "tz-names-etc",
    feature = "tz-names-europe",
    feature = "tz-names-indian",
    feature = "tz-names-pacific",
))]
fn name_lookup(
    arena: &'static str,
    strings: &[u32],
    runs: &[u32],
    keys: &[u16],
    ids: &[u16],
    loc: u16,
    key: u16,
) -> Option<&'static str> {
    let lo = *runs.get(loc as usize)? as usize;
    let hi = *runs.get(loc as usize + 1)? as usize;
    let at = lo + keys.get(lo..hi)?.binary_search(&key).ok()?;
    let id = *ids.get(at)? as usize;
    arena.get(*strings.get(id)? as usize..*strings.get(id + 1)? as usize)
}

/// `(area, index)` for a canonical zone id, or `None` when the zone is
/// unknown or its area is not compiled in.
pub(crate) fn zone_index(zone: &str) -> Option<(u8, u16)> {
    let (area, rest) = zone.split_once('/')?;
    Some(match area {
        #[cfg(feature = "tz-names-africa")]
        "Africa" => (0, zone_lookup(ZONES_AFRICA, &ZONE_STARTS_AFRICA, rest)?),
        #[cfg(feature = "tz-names-america")]
        "America" => (1, zone_lookup(ZONES_AMERICA, &ZONE_STARTS_AMERICA, rest)?),
        #[cfg(feature = "tz-names-antarctica")]
        "Antarctica" => (
            2,
            zone_lookup(ZONES_ANTARCTICA, &ZONE_STARTS_ANTARCTICA, rest)?,
        ),
        #[cfg(feature = "tz-names-arctic")]
        "Arctic" => (3, zone_lookup(ZONES_ARCTIC, &ZONE_STARTS_ARCTIC, rest)?),
        #[cfg(feature = "tz-names-asia")]
        "Asia" => (4, zone_lookup(ZONES_ASIA, &ZONE_STARTS_ASIA, rest)?),
        #[cfg(feature = "tz-names-atlantic")]
        "Atlantic" => (5, zone_lookup(ZONES_ATLANTIC, &ZONE_STARTS_ATLANTIC, rest)?),
        #[cfg(feature = "tz-names-australia")]
        "Australia" => (
            6,
            zone_lookup(ZONES_AUSTRALIA, &ZONE_STARTS_AUSTRALIA, rest)?,
        ),
        #[cfg(feature = "tz-names-etc")]
        "Etc" => (7, zone_lookup(ZONES_ETC, &ZONE_STARTS_ETC, rest)?),
        #[cfg(feature = "tz-names-europe")]
        "Europe" => (8, zone_lookup(ZONES_EUROPE, &ZONE_STARTS_EUROPE, rest)?),
        #[cfg(feature = "tz-names-indian")]
        "Indian" => (9, zone_lookup(ZONES_INDIAN, &ZONE_STARTS_INDIAN, rest)?),
        #[cfg(feature = "tz-names-pacific")]
        "Pacific" => (10, zone_lookup(ZONES_PACIFIC, &ZONE_STARTS_PACIFIC, rest)?),
        _ => return None,
    })
}

/// The metazone in effect for a zone at the UTC instant `unix`, or `None`
/// when CLDR maps it to none.
pub(crate) const fn metazone(area: u8, zone: u16, unix: i64) -> Option<u16> {
    match area {
        #[cfg(feature = "tz-names-africa")]
        0 => mz_africa(zone, unix),
        #[cfg(feature = "tz-names-america")]
        1 => mz_america(zone, unix),
        #[cfg(feature = "tz-names-antarctica")]
        2 => mz_antarctica(zone, unix),
        #[cfg(feature = "tz-names-arctic")]
        3 => mz_arctic(zone, unix),
        #[cfg(feature = "tz-names-asia")]
        4 => mz_asia(zone, unix),
        #[cfg(feature = "tz-names-atlantic")]
        5 => mz_atlantic(zone, unix),
        #[cfg(feature = "tz-names-australia")]
        6 => mz_australia(zone, unix),
        #[cfg(feature = "tz-names-etc")]
        7 => mz_etc(zone, unix),
        #[cfg(feature = "tz-names-europe")]
        8 => mz_europe(zone, unix),
        #[cfg(feature = "tz-names-indian")]
        9 => mz_indian(zone, unix),
        #[cfg(feature = "tz-names-pacific")]
        10 => mz_pacific(zone, unix),
        _ => None,
    }
}

/// A zone's tzdb region when that region has exactly one canonical zone —
/// UTS #35's condition for naming the *country* rather than the exemplar
/// city in the generic location format.
pub(crate) const fn single_zone_region(area: u8, zone: u16) -> Option<&'static str> {
    match area {
        #[cfg(feature = "tz-names-africa")]
        0 => rg_africa(zone),
        #[cfg(feature = "tz-names-america")]
        1 => rg_america(zone),
        #[cfg(feature = "tz-names-antarctica")]
        2 => rg_antarctica(zone),
        #[cfg(feature = "tz-names-arctic")]
        3 => rg_arctic(zone),
        #[cfg(feature = "tz-names-asia")]
        4 => rg_asia(zone),
        #[cfg(feature = "tz-names-atlantic")]
        5 => rg_atlantic(zone),
        #[cfg(feature = "tz-names-australia")]
        6 => rg_australia(zone),
        #[cfg(feature = "tz-names-etc")]
        7 => rg_etc(zone),
        #[cfg(feature = "tz-names-europe")]
        8 => rg_europe(zone),
        #[cfg(feature = "tz-names-indian")]
        9 => rg_indian(zone),
        #[cfg(feature = "tz-names-pacific")]
        10 => rg_pacific(zone),
        _ => None,
    }
}

/// The table index of `loc`'s nearest vendored CLDR ancestor, whose names
/// a sublocale inherits for every key it does not store itself.
pub(crate) const fn parent(loc: u16) -> Option<u16> {
    Some(match loc {
        21 => 20,
        22 => 21,
        23 => 21,
        24 => 21,
        26 => 25,
        40 => 24,
        54 => 53,
        80 => 79,
        93 => 92,
        108 => 107,
        110 => 109,
        111 => 110,
        _ => return None,
    })
}

/// A zone-level or metazone name string; see the key spaces above. A
/// sublocale stores only what differs from its ancestor, so a miss walks
/// up [`parent`].
pub(crate) fn name(area: u8, loc: u16, key: u16) -> Option<&'static str> {
    let mut loc = loc;
    loop {
        if let Some(s) = name_in(area, loc, key) {
            return Some(s);
        }
        loc = parent(loc)?;
    }
}

fn name_in(area: u8, loc: u16, key: u16) -> Option<&'static str> {
    match area {
        #[cfg(feature = "tz-names-africa")]
        0 => name_lookup(
            ARENA_AFRICA,
            &STRINGS_AFRICA,
            &RUNS_AFRICA,
            &KEYS_AFRICA,
            &IDS_AFRICA,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-america")]
        1 => name_lookup(
            ARENA_AMERICA,
            &STRINGS_AMERICA,
            &RUNS_AMERICA,
            &KEYS_AMERICA,
            &IDS_AMERICA,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-antarctica")]
        2 => name_lookup(
            ARENA_ANTARCTICA,
            &STRINGS_ANTARCTICA,
            &RUNS_ANTARCTICA,
            &KEYS_ANTARCTICA,
            &IDS_ANTARCTICA,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-arctic")]
        3 => name_lookup(
            ARENA_ARCTIC,
            &STRINGS_ARCTIC,
            &RUNS_ARCTIC,
            &KEYS_ARCTIC,
            &IDS_ARCTIC,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-asia")]
        4 => name_lookup(
            ARENA_ASIA,
            &STRINGS_ASIA,
            &RUNS_ASIA,
            &KEYS_ASIA,
            &IDS_ASIA,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-atlantic")]
        5 => name_lookup(
            ARENA_ATLANTIC,
            &STRINGS_ATLANTIC,
            &RUNS_ATLANTIC,
            &KEYS_ATLANTIC,
            &IDS_ATLANTIC,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-australia")]
        6 => name_lookup(
            ARENA_AUSTRALIA,
            &STRINGS_AUSTRALIA,
            &RUNS_AUSTRALIA,
            &KEYS_AUSTRALIA,
            &IDS_AUSTRALIA,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-etc")]
        7 => name_lookup(
            ARENA_ETC,
            &STRINGS_ETC,
            &RUNS_ETC,
            &KEYS_ETC,
            &IDS_ETC,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-europe")]
        8 => name_lookup(
            ARENA_EUROPE,
            &STRINGS_EUROPE,
            &RUNS_EUROPE,
            &KEYS_EUROPE,
            &IDS_EUROPE,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-indian")]
        9 => name_lookup(
            ARENA_INDIAN,
            &STRINGS_INDIAN,
            &RUNS_INDIAN,
            &KEYS_INDIAN,
            &IDS_INDIAN,
            loc,
            key,
        ),
        #[cfg(feature = "tz-names-pacific")]
        10 => name_lookup(
            ARENA_PACIFIC,
            &STRINGS_PACIFIC,
            &RUNS_PACIFIC,
            &KEYS_PACIFIC,
            &IDS_PACIFIC,
            loc,
            key,
        ),
        _ => None,
    }
}

