#[cfg(feature = "tz-names-atlantic")]
const fn mz_atlantic(zone: u16, unix: i64) -> Option<u16> {
    match zone {
        0 => {
            if unix < 725421600 {
                Some(31)
            } else if unix < 740278800 {
                Some(64)
            } else {
                Some(31)
            }
        }
        1 => Some(25),
        2 => Some(64),
        3 => Some(41),
        4 => Some(64),
        5 => Some(64),
        6 => Some(70),
        7 => Some(161),
        8 => Some(70),
        9 => Some(65),
        _ => None,
    }
}

