#[cfg(feature = "tz-names-australia")]
const fn mz_australia(zone: u16, unix: i64) -> Option<u16> {
    match zone {
        0 => Some(26),
        1 => Some(28),
        2 => Some(26),
        3 => Some(26),
        4 => Some(27),
        5 => Some(28),
        6 => Some(28),
        7 => {
            if unix < 352216800 {
                Some(28)
            } else {
                Some(113)
            }
        }
        8 => Some(28),
        9 => Some(29),
        10 => Some(28),
        _ => None,
    }
}

#[cfg(feature = "tz-names-australia")]
const fn rg_australia(zone: u16) -> Option<&'static str> {
    match zone {
        _ => None,
    }
}

