#[cfg(feature = "tz-names-indian")]
const fn mz_indian(zone: u16, unix: i64) -> Option<u16> {
    match zone {
        0 => Some(3),
        1 => Some(88),
        2 => Some(47),
        3 => Some(48),
        4 => Some(3),
        5 => Some(68),
        6 => Some(157),
        7 => Some(118),
        8 => Some(121),
        9 => Some(3),
        10 => Some(151),
        _ => None,
    }
}

#[cfg(feature = "tz-names-indian")]
const fn rg_indian(zone: u16) -> Option<&'static str> {
    match zone {
        0 => Some("MG"),
        1 => Some("IO"),
        2 => Some("CX"),
        3 => Some("CC"),
        4 => Some("KM"),
        5 => Some("TF"),
        6 => Some("SC"),
        7 => Some("MV"),
        8 => Some("MU"),
        9 => Some("YT"),
        10 => Some("RE"),
        _ => None,
    }
}

